"""
Continue a forced periodic orbit and solve its first and second implicit parameter responses.

Let $\mathcal F_\lambda(y)$ be one full driven period, formed from the source-based symmetric band steps with periodic endpoint forces. The requested branch is the periodic orbit connected to zero band displacement as the forcing amplitude is turned on:

$$\mathcal F_\lambda(y_*(\lambda))=y_*(\lambda),\qquad

M=\partial_y\mathcal F_0(y_*(0)).$$

Select that branch using eight nominal continuation amplitudes $1/8,2/8,\ldots,1$. At each amplitude solve the full vector shooting residual by Newton iteration, initialized from the preceding amplitude's solution. This avoids identifying a periodic orbit merely from a long undamped transient.



Implicit differentiation of the periodic boundary condition gives

$$ (I-M)y_*'=\partial_\lambda\mathcal F,$$

$$ (I-M)y_*''=\partial_{\lambda\lambda}\mathcal F+

2\,\partial_{y\lambda}\mathcal F\,y_*'+

\partial_{yy}\mathcal F[y_*',y_*'].$$

The linear system need not be symmetric. The eigenvalue one must be absent from the monodromy for the selected isolated branch. Partial derivatives on the right hold the initial point fixed, while the returned derivatives of $M(\lambda)=\partial_y\mathcal F_\lambda(y_*(\lambda))$ follow the moving periodic orbit. Repropagating the raw state and tangent jets with the solved initial derivative layers produces these total derivatives. The tangent starts at $I$ for each parameter, so its initial parameter derivatives vanish even though $y_*'$ and $y_*''$ do not. This distinction separates branch motion from variations in initial-condition tangent coordinates.

Returns
-------
np.ndarray, shape (3,2*k,1+2*k), periodic initial-state and orbit-following monodromy responses.
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def periodic_orbit_response(
    eq: "np.ndarray",
    ref: "np.ndarray",
    R: "np.ndarray",
    A: "np.ndarray",
    C: "np.ndarray",
    cubic: "np.ndarray",
    beta: "np.ndarray",
    force: "np.ndarray",
    drives: "np.ndarray",
    h: float,
    tol: float,
    maxiter: int,
) -> "np.ndarray":
    r"""Continue a forced periodic orbit and solve its first and second implicit parameter responses.

    Parameters
    ----------
    eq, ref, R : np.ndarray
        Relaxed reference (3,s,s+1), anchored band (3,k+s,k), harmonic map
        (3,2*k,2*k), for the fixed step h.
    A, C, cubic, beta, force : np.ndarray
        Static potential arrays (3,s,s), (j,s), (j,), (3,j), (3,s).
    drives : np.ndarray
        Shape (N+1,3,s), periodic Cartesian endpoint-force jets with identical
        first/last nodes; N>=2. All derivative layers are scaled during amplitude
        continuation, which uses the eight fixed fractions 1/8,...,1.
    h : float
        Positive step duration, with period T=N*h, held fixed in lambda.
    tol : float
        Positive absolute infinity-norm shooting tolerance.
    maxiter : int
        Positive maximum Newton updates per continuation amplitude. Initialize
        at y=0, carry each root to the next amplitude, and use residual backtracking.

    Returns
    -------
    result, np.ndarray
        Shape (3,2*k,1+2*k), column 0 is the periodic initial state and its
        first two parameter derivatives; remaining columns are the full-period
        monodromy and its total first/second derivatives along that orbit.
        The continued branch is isolated with nonsingular I-M throughout.

    Raises
    ------
    ValueError
        If Newton shooting or its residual-decreasing line search fails.

    All derivative arrays have leading axis (value, first derivative, second derivative) at lambda=0, with no factorial scaling. All data are real, finite, and conforming; inputs must be preserved.
    """
    return result

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np


def _period_response(initial, eq, ref, R, A, C, cubic, beta, force, drives, h):
    dim = initial.shape[1]
    jet = np.zeros((3, dim, 1 + dim))
    jet[:, :, 0] = initial
    jet[0, :, 1:] = np.eye(dim)
    for i in range(len(drives) - 1):
        jet = _oracle_driven_band_jet_step(
            jet, eq, ref, R, A, C, cubic, beta, force, drives[i], drives[i + 1], h
        )
    return jet


def _oracle_periodic_orbit_response(
    eq: "np.ndarray",
    ref: "np.ndarray",
    R: "np.ndarray",
    A: "np.ndarray",
    C: "np.ndarray",
    cubic: "np.ndarray",
    beta: "np.ndarray",
    force: "np.ndarray",
    drives: "np.ndarray",
    h: float,
    tol: float,
    maxiter: int,
) -> "np.ndarray":
    k = ref.shape[2]
    dim = 2 * k
    initial = np.zeros((3, dim))
    for amplitude in np.arange(1, 9) / 8:
        drive = drives * amplitude
        for iteration in range(maxiter + 1):
            end = _period_response(
                initial, eq, ref, R, A, C, cubic, beta, force, drive, h
            )
            residual = end[0, :, 0] - initial[0]
            norm = np.linalg.norm(residual, ord=np.inf)
            if norm <= tol:
                break
            if iteration == maxiter:
                raise ValueError("periodic shooting failed")
            delta = np.linalg.solve(end[0, :, 1:] - np.eye(dim), -residual)
            alpha = 1.0
            for _ in range(25):
                trial = initial.copy()
                trial[0] += alpha * delta
                trialend = _period_response(
                    trial, eq, ref, R, A, C, cubic, beta, force, drive, h
                )
                trialnorm = np.linalg.norm(trialend[0, :, 0] - trial[0], ord=np.inf)
                if trialnorm <= (1 - 1e-4 * alpha) * norm:
                    initial = trial
                    break
                alpha *= 0.5
            else:
                raise ValueError("shooting line search failed")
    end = _period_response(initial, eq, ref, R, A, C, cubic, beta, force, drives, h)
    boundary = np.eye(dim) - end[0, :, 1:]
    initial[1] = np.linalg.solve(boundary, end[1, :, 0])
    first = _period_response(initial, eq, ref, R, A, C, cubic, beta, force, drives, h)
    initial[2] = np.linalg.solve(boundary, first[2, :, 0])
    total = _period_response(initial, eq, ref, R, A, C, cubic, beta, force, drives, h)
    result = total.copy()
    result[:, :, 0] = initial
    return result

